public class PassByValue {
    static int bump(int n) {
        n = n + 1;
        return n;
    }
    static void addTo(java.util.List<String> xs) {
        xs.add("added");
        xs = new java.util.ArrayList<>();
        xs.add("ignored");
    }
    public static void main(String[] args) {
        int count = 5;
        int back = bump(count);
        System.out.println(count + " " + back);

        java.util.List<String> names = new java.util.ArrayList<>();
        names.add("first");
        addTo(names);
        System.out.println(names);
    }
}

