public class Dispatch {
    static class Source {
        String name() { return "Source"; }
        static String kind() { return "static-Source"; }
        String describe() { return name() + "/" + kind(); }
    }
    static class Kafka extends Source {
        @Override String name() { return "Kafka"; }
        static String kind() { return "static-Kafka"; }
    }
    public static void main(String[] args) {
        Source s = new Kafka();
        System.out.println(s.name());
        System.out.println(Source.kind());
        System.out.println(s.describe());
    }
}

public class FinallyReturn {
    static int leaky() {
        int value = 1;
        try {
            return value;
        } finally {
            value = 2;
        }
    }
    static int overriding() {
        try {
            return 1;
        } finally {
            return 2;
        }
    }
    public static void main(String[] args) {
        System.out.println(leaky());
        System.out.println(overriding());
    }
}

public class ResourceOrder {
    static class Res implements AutoCloseable {
        final String tag;
        Res(String tag) { this.tag = tag; System.out.println("open " + tag); }
        public void close() { System.out.println("close " + tag); }
    }
    public static void main(String[] args) {
        try (Res conn = new Res("Connection");
             Res stmt = new Res("PreparedStatement");
             Res rs   = new Res("ResultSet")) {
            System.out.println("work");
            throw new IllegalStateException("boom");
        } catch (IllegalStateException e) {
            System.out.println("caught " + e.getMessage());
        } finally {
            System.out.println("finally");
        }
    }
}

