-- ============================================
-- SHOPFLOW INDEXING STRATEGY
-- ============================================

-- 1. Primary indexes (automatic)
-- customer_id, product_id, order_id already indexed

-- 2. Foreign key indexes (essential for JOINs)
CREATE INDEX idx_orders_customer_id ON orders(customer_id);
CREATE INDEX idx_order_items_order_id ON order_items(order_id);
CREATE INDEX idx_order_items_product_id ON order_items(product_id);
CREATE INDEX idx_reviews_product_id ON reviews(product_id);

-- 3. Composite index for common query patterns
-- Query: Find orders by customer in date range
CREATE INDEX idx_orders_customer_date 
ON orders(customer_id, order_date DESC);

-- This index supports:
-- ✅ WHERE customer_id = 1
-- ✅ WHERE customer_id = 1 AND order_date > '2024-01-01'
-- ✅ WHERE customer_id = 1 ORDER BY order_date DESC
-- ❌ WHERE order_date > '2024-01-01' (no leftmost column)

-- 4. Covering index (includes all needed columns)
CREATE INDEX idx_orders_covering 
ON orders(customer_id, order_date, status, total_amount);

-- Query uses index-only scan (no table access needed)
SELECT customer_id, order_date, status, total_amount
FROM orders
WHERE customer_id = 1 AND order_date > '2024-01-01';

-- 5. Partial index (PostgreSQL) - only index active products
CREATE INDEX idx_products_active 
ON products(category, price) 
WHERE is_active = TRUE;

-- 6. Expression index
CREATE INDEX idx_customers_email_lower 
ON customers(LOWER(email));

-- Now this query can use the index
SELECT * FROM customers WHERE LOWER(email) = 'john.smith@email.com';

-- 7. Full-text index for product search
-- MySQL
ALTER TABLE products ADD FULLTEXT INDEX idx_product_search(product_name);
SELECT * FROM products 
WHERE MATCH(product_name) AGAINST('iPhone Pro' IN NATURAL LANGUAGE MODE);

-- PostgreSQL
CREATE INDEX idx_products_search ON products 
USING GIN(to_tsvector('english', product_name));
SELECT * FROM products 
WHERE to_tsvector('english', product_name) @@ to_tsquery('iPhone & Pro');

