-- ❌ BAD: Function on indexed column (not sargable)
SELECT * FROM employees WHERE YEAR(hire_date) = 2023;
-- ✅ GOOD: Range query (can use index)
SELECT * FROM employees 
WHERE hire_date >= '2023-01-01' AND hire_date < '2024-01-01';

-- ❌ BAD: Leading wildcard
SELECT * FROM employees WHERE name LIKE '%smith';
-- ✅ GOOD: Trailing wildcard (or use full-text search)
SELECT * FROM employees WHERE name LIKE 'Smith%';

-- ❌ BAD: OR on different columns (can't use single index efficiently)
SELECT * FROM employees WHERE dept_id = 1 OR location_id = 5;
-- ✅ GOOD: UNION ALL (can use separate indexes)
SELECT * FROM employees WHERE dept_id = 1
UNION ALL
SELECT * FROM employees WHERE location_id = 5;

-- ❌ BAD: SELECT *
SELECT * FROM employees WHERE id = 1;
-- ✅ GOOD: Specific columns
SELECT id, name, email FROM employees WHERE id = 1;

-- ❌ BAD: NOT IN with potential NULLs
SELECT * FROM orders WHERE customer_id NOT IN (SELECT id FROM inactive_customers);
-- ✅ GOOD: NOT EXISTS (NULL-safe)
SELECT * FROM orders o 
WHERE NOT EXISTS (SELECT 1 FROM inactive_customers ic WHERE ic.id = o.customer_id);

-- ❌ BAD: LEFT JOIN with WHERE on right table (becomes INNER JOIN!)
SELECT * FROM employees e
LEFT JOIN departments d ON e.dept_id = d.id
WHERE d.name = 'IT';  -- Filters out NULLs from LEFT JOIN!
-- ✅ GOOD: Move filter to ON clause
SELECT * FROM employees e
LEFT JOIN departments d ON e.dept_id = d.id AND d.name = 'IT';

