# Decorator: A function that modifies another function
def timer_decorator(func):
    import time
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__} took {end - start:.2f}s")
        return result
    return wrapper

@timer_decorator
def slow_function():
    import time
    time.sleep(1)
    return "Done"

# Practical example: Database connection decorator
def with_connection(func):
    def wrapper(*args, **kwargs):
        conn = get_db_connection()
        try:
            result = func(conn, *args, **kwargs)
            conn.commit()
            return result
        except Exception as e:
            conn.rollback()
            raise e
        finally:
            conn.close()
    return wrapper

@with_connection
def create_user(conn, name, email):
    cursor = conn.cursor()
    cursor.execute("INSERT INTO users (name, email) VALUES (?, ?)", (name, email))

class Employee:
    # Class variable (shared by all instances)
    company = "Tech Corp"

    # Constructor
    def __init__(self, name: str, salary: float):
        self.name = name           # Public instance variable
        self._salary = salary      # Protected (convention)
        self.__id = id(self)       # Private (name mangling)

    # Instance method
    def get_info(self):
        return f"{self.name} earns {self._salary}"

    # Property decorator (getter)
    @property
    def salary(self):
        return self._salary

    # Property setter
    @salary.setter
    def salary(self, value):
        if value < 0:
            raise ValueError("Negative salary")
        self._salary = value

    # Class method (works with class, not instance)
    @classmethod
    def from_dict(cls, data):
        return cls(data['name'], data['salary'])

    # Static method (no access to class or instance)
    @staticmethod
    def is_valid_salary(salary):
        return salary > 0

    # String representations
    def __str__(self):
        return f"Employee({self.name})"

    def __repr__(self):
        return f"Employee('{self.name}', {self._salary})"

