import mysql.connector
from mysql.connector import Error

class MySQLDatabase:
    def __init__(self, host, database, user, password):
        self.config = {
            'host': host,
            'database': database,
            'user': user,
            'password': password
        }
        self.connection = None

    def connect(self):
        try:
            self.connection = mysql.connector.connect(**self.config)
            if self.connection.is_connected():
                print("Connected to MySQL")
        except Error as e:
            print(f"Error: {e}")

    def disconnect(self):
        if self.connection and self.connection.is_connected():
            self.connection.close()

    # CREATE
    def create(self, name, email, salary):
        query = "INSERT INTO employees (name, email, salary) VALUES (%s, %s, %s)"
        cursor = self.connection.cursor()
        cursor.execute(query, (name, email, salary))
        self.connection.commit()
        return cursor.lastrowid

    # READ
    def read_all(self):
        query = "SELECT * FROM employees"
        cursor = self.connection.cursor(dictionary=True)
        cursor.execute(query)
        return cursor.fetchall()

    def read_by_id(self, emp_id):
        query = "SELECT * FROM employees WHERE id = %s"
        cursor = self.connection.cursor(dictionary=True)
        cursor.execute(query, (emp_id,))
        return cursor.fetchone()

    # UPDATE
    def update(self, emp_id, name=None, email=None, salary=None):
        updates = []
        values = []
        if name:
            updates.append("name = %s")
            values.append(name)
        if email:
            updates.append("email = %s")
            values.append(email)
        if salary:
            updates.append("salary = %s")
            values.append(salary)

        if not updates:
            return False

        query = f"UPDATE employees SET {', '.join(updates)} WHERE id = %s"
        values.append(emp_id)

        cursor = self.connection.cursor()
        cursor.execute(query, tuple(values))
        self.connection.commit()
        return cursor.rowcount > 0

    # DELETE
    def delete(self, emp_id):
        query = "DELETE FROM employees WHERE id = %s"
        cursor = self.connection.cursor()
        cursor.execute(query, (emp_id,))
        self.connection.commit()
        return cursor.rowcount > 0

from sqlalchemy import create_engine, Column, Integer, String, Float
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker

Base = declarative_base()

# Model Definition
class Employee(Base):
    __tablename__ = 'employees'

    id = Column(Integer, primary_key=True, autoincrement=True)
    name = Column(String(100), nullable=False)
    email = Column(String(100), unique=True)
    salary = Column(Float)

    def __repr__(self):
        return f"<Employee(name='{self.name}', email='{self.email}')>"

    def to_dict(self):
        return {
            'id': self.id,
            'name': self.name,
            'email': self.email,
            'salary': self.salary
        }

# Database Setup
engine = create_engine('postgresql://user:pass@localhost/dbname')
Base.metadata.create_all(engine)
Session = sessionmaker(bind=engine)

# CRUD Operations
class EmployeeRepository:
    def __init__(self):
        self.session = Session()

    # CREATE
    def create(self, name, email, salary):
        employee = Employee(name=name, email=email, salary=salary)
        self.session.add(employee)
        self.session.commit()
        return employee

    # READ
    def get_all(self):
        return self.session.query(Employee).all()

    def get_by_id(self, emp_id):
        return self.session.query(Employee).filter(Employee.id == emp_id).first()

    def get_by_filter(self, **filters):
        query = self.session.query(Employee)
        for key, value in filters.items():
            query = query.filter(getattr(Employee, key) == value)
        return query.all()

    # UPDATE
    def update(self, emp_id, **kwargs):
        employee = self.get_by_id(emp_id)
        if employee:
            for key, value in kwargs.items():
                setattr(employee, key, value)
            self.session.commit()
            return employee
        return None

    # DELETE
    def delete(self, emp_id):
        employee = self.get_by_id(emp_id)
        if employee:
            self.session.delete(employee)
            self.session.commit()
            return True
        return False

    def close(self):
        self.session.close()

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import Optional

app = FastAPI()

class UserCreate(BaseModel):
    name: str
    email: str

class UserUpdate(BaseModel):
    name: Optional[str] = None
    email: Optional[str] = None

class UserResponse(BaseModel):
    id: int
    name: str
    email: str

users_db = {}
counter = 0

@app.post("/users", response_model=UserResponse)
def create_user(user: UserCreate):
    global counter
    counter += 1
    users_db[counter] = {"id": counter, **user.dict()}
    return users_db[counter]

@app.get("/users/{user_id}", response_model=UserResponse)
def read_user(user_id: int):
    if user_id not in users_db:
        raise HTTPException(status_code=404, detail="User not found")
    return users_db[user_id]

@app.get("/users", response_model=list[UserResponse])
def read_users(skip: int = 0, limit: int = 10):
    return list(users_db.values())[skip:skip+limit]

@app.put("/users/{user_id}", response_model=UserResponse)
def update_user(user_id: int, user: UserUpdate):
    if user_id not in users_db:
        raise HTTPException(status_code=404, detail="User not found")
    stored = users_db[user_id]
    update_data = user.dict(exclude_unset=True)
    users_db[user_id] = {**stored, **update_data}
    return users_db[user_id]

@app.delete("/users/{user_id}")
def delete_user(user_id: int):
    if user_id not in users_db:
        raise HTTPException(status_code=404, detail="User not found")
    del users_db[user_id]
    return {"message": "User deleted"}

