/**
 * Database connection manager using connection pooling pattern.
 */
public class DatabaseConnection {
    private static final String URL = "jdbc:mysql://localhost:3306/shopflow";
    private static final String USER = "root";
    private static final String PASSWORD = "password";

    private Connection connection;

    public void connect() throws SQLException {
        try {
            // Load driver (optional in modern JDBC)
            Class.forName("com.mysql.cj.jdbc.Driver");

            // Establish connection
            connection = DriverManager.getConnection(URL, USER, PASSWORD);
            connection.setAutoCommit(false);  // Manual transaction control

            System.out.println("Connected to database successfully");

        } catch (ClassNotFoundException e) {
            throw new SQLException("MySQL Driver not found", e);
        }
    }

    public void disconnect() {
        if (connection != null) {
            try {
                connection.close();
                System.out.println("Database connection closed");
            } catch (SQLException e) {
                System.err.println("Error closing connection: " + e.getMessage());
            }
        }
    }

    public Connection getConnection() {
        return connection;
    }

    public void commit() throws SQLException {
        connection.commit();
    }

    public void rollback() {
        try {
            connection.rollback();
        } catch (SQLException e) {
            System.err.println("Error during rollback: " + e.getMessage());
        }
    }
}


