public boolean transferEmployee(int empId, int fromDept, int toDept) {
    String updateOld = "UPDATE departments SET employee_count = employee_count - 1 WHERE id = ?";
    String updateNew = "UPDATE departments SET employee_count = employee_count + 1 WHERE id = ?";
    String updateEmp = "UPDATE employees SET department_id = ? WHERE id = ?";

    Connection conn = null;
    try {
        conn = getConnection();
        conn.setAutoCommit(false);  // Start transaction

        try (PreparedStatement pstmt1 = conn.prepareStatement(updateOld);
             PreparedStatement pstmt2 = conn.prepareStatement(updateNew);
             PreparedStatement pstmt3 = conn.prepareStatement(updateEmp)) {

            pstmt1.setInt(1, fromDept);
            pstmt1.executeUpdate();

            pstmt2.setInt(1, toDept);
            pstmt2.executeUpdate();

            pstmt3.setInt(1, toDept);
            pstmt3.setInt(2, empId);
            pstmt3.executeUpdate();

            conn.commit();  // Commit transaction
            return true;
        }
    } catch (SQLException e) {
        if (conn != null) {
            try {
                conn.rollback();  // Rollback on error
            } catch (SQLException ex) {
                ex.printStackTrace();
            }
        }
        e.printStackTrace();
    } finally {
        if (conn != null) {
            try {
                conn.setAutoCommit(true);
                conn.close();
            } catch (SQLException e) {
                e.printStackTrace();
            }
        }
    }
    return false;
}

