    @wraps(func)  # Preserves function metadata
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        duration = time.time() - start
        print(f'{func.__name__} took {duration:.4f} seconds')
        return result
    return wrapper

