import logging

def log_execution(level=logging.INFO):
    """Log function execution with parameters and result."""

    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            logger = logging.getLogger(func.__module__)
            logger.log(level, f"Calling {func.__name__} with args={args}, kwargs={kwargs}")

            try:
                result = func(*args, **kwargs)
                logger.log(level, f"{func.__name__} returned {result}")
                return result
            except Exception as e:
                logger.error(f"{func.__name__} raised {type(e).__name__}: {e}")
                raise
        return wrapper
    return decorator

@log_execution(level=logging.DEBUG)
def calculate_total(items: list) -> float:
    """Calculate order total."""
    return sum(item['price'] * item['qty'] for item in items)

