def load_receipts(text):
    rows = list(csv.DictReader(io.StringIO(text)))
    seen = set()
    accepted, rejected = [], []
    for line, row in enumerate(rows, 2):
        reasons = []
        receipt_id = row.get("id", "").strip()
        if not receipt_id:
            reasons.append("missing id")
        elif receipt_id in seen:
            reasons.append("duplicate id")
        else:
            seen.add(receipt_id)
        if row.get("status") not in {"OK", "FAILED"}:
            reasons.append("invalid status")
        if not row.get("operator", "").strip():
            reasons.append("missing operator")
        try:
            amount = int(row.get("amount", ""))
            if amount < 0:
                reasons.append("negative amount")
        except (ValueError, TypeError):
            reasons.append("amount must be an integer")
            amount = None
        if reasons:
            rejected.append({"line": line, "reasons": reasons, "record": row})
        else:
            accepted.append({**row, "id": receipt_id, "amount": amount})
    assert len(accepted) + len(rejected) == len(rows)
    return accepted, rejected

def summarize(rows):
    successful = [row for row in rows if row["status"] == "OK"]
    totals = defaultdict(int)
    for row in successful:
        totals[row["operator"]] += row["amount"]
    return {"rows": len(rows), "successful_count": len(successful),
            "successful_total": sum(row["amount"] for row in successful),
            "success_rate_percent": 100 * len(successful) / len(rows) if rows else None,
            "operator_totals": dict(totals)}

