function uhub_switchInnerTab(group,tab){
  const prefix=group+'-';
  document.querySelectorAll('[id^="'+prefix+'"]').forEach(el=>{
    if(el.classList.contains('tab-content'))el.classList.remove('active');
  });
  const pane=document.getElementById(prefix+tab);
  if(pane)pane.classList.add('active');
  const parent=pane?.closest('.page');
  if(parent){
    const tabs=parent.querySelectorAll('.tabs .tab');
    tabs.forEach(t=>t.classList.remove('active'));
    if(event&&event.target)event.target.classList.add('active');
  }
}

