function ulinuxpro_resolvePath(path) {
    if (path === "..") {
        let parts = ulinuxpro_currentPath.split("/");
        parts.pop();
        return parts.join("/") || "/";
    }
    if (path.startsWith("/")) return path;
    return ulinuxpro_currentPath + "/" + path;
}

