(function(){
  var pre=document.getElementById('ref'), q=document.getElementById('q'), c=document.getElementById('count');
  var lines=pre.textContent.split('\n');
  function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
  function render(){
    var term=(q.value||'').trim().toLowerCase();
    var out=[], shown=0, total=lines.length;
    for(var i=0;i<lines.length;i++){
      var line=lines[i];
      if(term && line.toLowerCase().indexOf(term)===-1) continue;
      var safe=esc(line);
      if(term){
        var re=new RegExp('('+term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig');
        safe=safe.replace(re,'<mark>$1</mark>');
      }
      shown++;
      out.push(safe);
    }
    pre.innerHTML=out.join('\n');
    c.textContent=term?('Showing '+shown+' of '+total+' lines'):(total+' lines');
  }
  q.addEventListener('input',render);
  render();
})();

// PARTICLES
function unextgendim_buildParticles(){
  const canvas=document.getElementById('particleCanvas');
  if(!canvas)return;
  const ctx=canvas.getContext('2d');
  let w,h,particles=[];
  function resize(){w=canvas.width=canvas.offsetWidth;h=canvas.height=canvas.offsetHeight}
  resize();window.addEventListener('resize',resize);
  for(let i=0;i<60;i++)particles.push({x:Math.random()*w,y:Math.random()*h,vx:(Math.random()-0.5)*0.5,vy:(Math.random()-0.5)*0.5,r:Math.random()*2+1});
  function draw(){
    ctx.clearRect(0,0,w,h);
    particles.forEach(p=>{
      p.x+=p.vx;p.y+=p.vy;
      if(p.x<0||p.x>w)p.vx*=-1;
      if(p.y<0||p.y>h)p.vy*=-1;
      ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle='rgba(255,121,0,0.4)';ctx.fill();
    });
    for(let i=0;i<particles.length;i++)for(let j=i+1;j<particles.length;j++){
      const dx=particles[i].x-particles[j].x,dy=particles[i].y-particles[j].y,d=Math.sqrt(dx*dx+dy*dy);
      if(d<120){ctx.beginPath();ctx.moveTo(particles[i].x,particles[i].y);ctx.lineTo(particles[j].x,particles[j].y);ctx.strokeStyle=`rgba(255,121,0,${0.15*(1-d/120)})`;ctx.stroke()}
    }
    requestAnimationFrame(draw);
  }
  draw();
}

