class Node:
    def __init__(self, value):
        self.value, self.left, self.right = value, None, None
    def add(self, value):
        side = "left" if value < self.value else "right"
        child = getattr(self, side)
        if child is None: setattr(self, side, Node(value))
        else: child.add(value)
root = Node(5)
for n in [3, 7, 4]: root.add(n)
