def mse(actual, predicted):
    if len(actual) != len(predicted): raise ValueError("length mismatch")
    return sum((a-p)**2 for a,p in zip(actual,predicted)) / len(actual)
print(round(mse([1,2,3],[1,2,4]), 3))

from math import sqrt
def cosine(a,b):
    dot=sum(x*y for x,y in zip(a,b))
    na=sqrt(sum(x*x for x in a)); nb=sqrt(sum(y*y for y in b))
    if not na or not nb: raise ValueError("zero vector")
    return dot/(na*nb)
print(round(cosine([1,0,1],[1,0,1]), 3))
